const TZ = 'Europe/Lisbon';
const hoje = DateTime.now().setZone(TZ).startOf('day');
const hojeStr = hoje.toFormat('yyyy-MM-dd');
function parseData(v) {
  if (!v) return null;
  const s = String(v).trim();
  let d = DateTime.fromISO(s, { zone: TZ });
  if (!d.isValid) d = DateTime.fromFormat(s, 'dd/MM/yyyy', { zone: TZ });
  return d.isValid ? d.startOf('day') : null;
}
function diasDesde(v) {
  const d = parseData(v);
  return d ? Math.floor(hoje.diff(d, 'days').days) : Infinity;
}

const cfg = $('Config').first().json;
const proximo = wd => hoje.plus({ days: ((wd - hoje.weekday + 7) % 7) || 7 });
const datas = { terca: proximo(2), quarta: proximo(3), quinta: proximo(4) };
const comLeadMagnet = datas.quinta.day <= 7; // 1.ª semana do mês

const anteriores = $input.all()
  .map(i => i.json)
  .filter(r => r.texto)
  .slice(-9)
  .map(r => String(r.texto).slice(0, 300));

const system = `És ghostwriter de LinkedIn de ${cfg.nome_remetente}, que ${cfg.oferta}.
Público: ${cfg.icp}. Dor principal: ${cfg.dor}. Prova disponível: ${cfg.prova}. Temas: ${cfg.temas}.

Escreve 3 publicações em português de Portugal:
- terca (educativo): framework, passo a passo ou erro comum. Objetivo: autoridade.
- quarta (prova): caso de cliente com números, antes e depois. Usa apenas a prova fornecida, sem inventar números.
- quinta (opiniao): ponto de vista contrário ou história de bastidores. Objetivo: alcance e ligação.
${comLeadMagnet ? `A de quinta termina com CTA de lead magnet: ${cfg.lead_magnet}.` : ''}

Formato: gancho forte nas 2 primeiras linhas; frases curtas e espaçadas; uma ideia por publicação; 900–1500 caracteres; CTA leve no fim (pergunta); sem links; 0–3 hashtags no fim; sem emojis em excesso.
Não repitas ideias nem ganchos das publicações anteriores.`;

return [{ json: {
  datas: Object.fromEntries(Object.entries(datas).map(([k, d]) => [k, d.toFormat('yyyy-MM-dd')])),
  claude_request: {
    model: 'claude-opus-5',
    max_tokens: 16000,
    fallbacks: 'default',
    output_config: {
      effort: 'high',
      format: {
        type: 'json_schema',
        schema: {
          type: 'object',
          properties: {
            posts: {
              type: 'array',
              items: {
                type: 'object',
                properties: {
                  dia: { type: 'string', enum: ['terca', 'quarta', 'quinta'] },
                  tipo: { type: 'string' },
                  texto: { type: 'string' },
                },
                required: ['dia', 'tipo', 'texto'],
                additionalProperties: false,
              },
            },
          },
          required: ['posts'],
          additionalProperties: false,
        },
      },
    },
    system,
    messages: [{ role: 'user', content: 'Publicações anteriores (não repetir):\n' + (anteriores.join('\n---\n') || '(nenhuma)') }],
  },
} }];

const datas = $('Preparar pedido de conteúdo').first().json.datas;
const r = $input.first().json;
const bloco = (r.content || []).find(c => c.type === 'text');
if (!bloco) throw new Error('Claude não devolveu texto (stop_reason: ' + r.stop_reason + ')');
return JSON.parse(bloco.text).posts.map(p => ({ json: {
  id: datas[p.dia],
  data_publicacao: datas[p.dia],
  dia: p.dia,
  tipo: p.tipo,
  texto: p.texto,
  estado: 'rascunho',
} }));
